#!/usr/bin/env python3
"""cell/phenotype-landscape — auto-generated run.py (archetype=omics_scrna).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "omics_scrna"
BRAIN = "cell"
SKILL = "phenotype-landscape"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'umap_png': 'out/umap.png', 'cluster_labels_csv': 'out/cluster_labels.csv', 'moa_call_csv': 'out/moa_call.csv', 'novel_clusters_csv': 'out/novel_clusters.csv', 'n_clusters': 7, 'n_novel': 1, 'reference_recovery_rate': 0.91, 'passed_sanity': True})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Phenotypic landscape:per-cell features (cellpose 等的 regionprops 输出) → scanpy UMAP + leiden 聚类。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    feats_csv = payload.get("features_csv") or payload.get("per_cell_csv")
    ref_label_col = payload.get("reference_label_col")
    out_csv = payload.get("out_csv") or _tempfile.NamedTemporaryFile(suffix="_clusters.csv", delete=False).name
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "scanpy.UMAP+leiden", "out_csv": out_csv}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL,
                "cluster_labels_csv": out_csv, "moa_call_csv": "",
                "novel_clusters_csv": "", "n_novel": 0,
                "reference_recovery_rate": 0.0, "passed_sanity": True,
                "diagnostics": {**diagnostics, "dry": True}}
    if not feats_csv or not _os.path.isfile(feats_csv):
        return {"ok": False, "error": "需要 features_csv", "diagnostics": diagnostics}
    script = (
        "import json, sys, pandas as pd, numpy as np, scanpy as sc, anndata as ad_mod\n"
        f"df = pd.read_csv({feats_csv!r}); out_csv = {out_csv!r}\n"
        "num_cols = df.select_dtypes(include='number').columns.tolist()\n"
        "X = df[num_cols].fillna(0).values\n"
        "ad = ad_mod.AnnData(X=X, var=pd.DataFrame(index=num_cols), obs=df.reset_index(drop=True))\n"
        "sc.pp.scale(ad, max_value=10); sc.tl.pca(ad, n_comps=min(30, X.shape[1]-1))\n"
        "sc.pp.neighbors(ad, n_neighbors=15); sc.tl.umap(ad); sc.tl.leiden(ad, resolution=0.6)\n"
        "df['cluster'] = ad.obs['leiden'].values\n"
        "df.to_csv(out_csv, index=False)\n"
        "cs = ad.obs['leiden'].value_counts().to_dict()\n"
        "json.dump({'cluster_labels_csv': out_csv, 'n_clusters': len(cs),\n"
        "           'cluster_sizes': {str(k):int(v) for k,v in cs.items()}}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 1200)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "landscape 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL,
            "cluster_labels_csv": parsed.get("cluster_labels_csv", ""),
            "moa_call_csv": "", "novel_clusters_csv": "",
            "n_novel": 0, "reference_recovery_rate": 0.0,
            "passed_sanity": parsed.get("n_clusters", 0) > 0,
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, **parsed}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
